// swift-tools-version: 5.9
import PackageDescription

// The framework map (BASIC-45): what lets a program BASICStudio runs as
// WebAssembly IMPORT a framework Studio itself contains — ActiveUI and
// TUIKit — on a Mac or an iPad, with no swiftc and no `swift build` there.
//
// Everything in Sources/BASICFrameworkMap except FrameworkMap.swift is
// generated by `basicc framework-map` (Code/Scripts/generate-framework-map.sh):
// R4's shims for every member, the entries that call them by name, and each
// framework's symbol graph for the compiler Studio carries.
//
// Swift 5 language mode on purpose: the shims are R4's, generated for
// basicc's native Swift dialect, where they compile in Swift 5 mode, and
// Studio builds in Swift 6. A package of its own keeps them in theirs.
let package = Package(
    name: "BASICFrameworkMap",
    platforms: [.macOS("16.0"), .iOS("17.0")],
    products: [
        .library(name: "BASICFrameworkMap", targets: ["BASICFrameworkMap"]),
    ],
    dependencies: [
        .package(path: "../../../../AIResearch/ActiveUI/Code/ActiveUI"),
        .package(path: "../../../frameworks/UILess/Code/TUIKit"),
        .package(path: "../BASICCompiler"),
    ],
    targets: [
        .target(
            name: "BASICFrameworkMap",
            dependencies: [
                .product(name: "ActiveUI", package: "ActiveUI"),
                .product(name: "TUIKit", package: "TUIKit"),
                .product(name: "BASICWasmRunner", package: "BASICCompiler"),
                // The runtime's half of a shim: strings, records, errors.
                .product(name: "BASICRTSwift", package: "BASICCompiler"),
            ],
            resources: [.copy("Resources")]
        ),
        .testTarget(
            name: "BASICFrameworkMapTests",
            dependencies: [
                "BASICFrameworkMap",
                .product(name: "BASICDialectSwift", package: "BASICCompiler"),
                .product(name: "BASICRTSwift", package: "BASICCompiler"),
                .product(name: "BASICRT", package: "BASICCompiler"),
                .product(name: "ActiveUI", package: "ActiveUI"),
            ]
        ),
    ]
)
